import React from 'react';
import './services.css';
import { FaArrowRight, FaPaintRoller, FaIndustry, FaLeaf, FaLayerGroup } from 'react-icons/fa';
import { GiSpikedFence, GiGate } from "react-icons/gi";
import { TbFence } from "react-icons/tb";
import { LuFence } from "react-icons/lu";
import { SERVICES, SERVICES_SECTION, ServiceData } from '../../content';

const Services: React.FC = () => {
  const getServiceIcon = (iconName: string) => {
    switch (iconName) {
      case 'TbFence': return <TbFence />;
      case 'FaPaintRoller': return <FaPaintRoller />;
      case 'FaIndustry': return <FaIndustry />;
      case 'GiSpikedFence': return <GiSpikedFence />;
      case 'LuFence': return <LuFence />;
      case 'FaLeaf': return <FaLeaf />;
      case 'FaLayerGroup': return <FaLayerGroup />;
      case 'GiGate': return <GiGate />;
      default: return <TbFence />;
    }
  };

  return (
    <section className="services" id="services">
      <div className="services-container">
        <div className="services-header">
          <div className="section-tag">
            <span>{SERVICES_SECTION.badge}</span>
          </div>
          <h2 className="services-title">
            {SERVICES_SECTION.title}
          </h2>
          <p className="services-subtitle">
            {SERVICES_SECTION.subtitle}
          </p>
        </div>

        <div className="services-grid">
          {SERVICES.map((service: ServiceData) => (
            <div className="service-card" key={service.id}>
              <div className="card-image">
                <img src={service.image} alt={service.title} />
                <div className="card-icon">{getServiceIcon(service.icon as string)}</div>
              </div>
              <div className="card-content">
                <h3 className="card-title">{service.title}</h3>
                <p className="card-description">{service.description}</p>
                <a href={service.slug} className="card-btn">
                  Learn More <FaArrowRight className="btn-icon" />
                </a>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Services;
