import React from 'react';
import './hero.css';
import { FaStar, FaGoogle, FaFacebookF, FaChevronRight, FaQuoteLeft, FaList, FaFolderOpen, FaComments } from 'react-icons/fa';
import { HERO, BUSINESS } from '../../content';
import hero from '../../images/hero.jpg'
const Hero: React.FC = () => {
  const getIcon = (iconName: string) => {
    switch (iconName) {
      case 'google': return <FaGoogle />;
      case 'facebook': return <FaFacebookF />;
      case 'list': return <FaList />;
      case 'folder': return <FaFolderOpen />;
      case 'comment': return <FaComments />;
      case 'star': return <FaStar />;
      default: return <FaStar />;
    }
  };

  const reviewerInitials = HERO.reviewerName
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0].toUpperCase())
    .join('');

  return (
    <section className="hero">
      {/* Background with focal point on the hands */}
      <div className="hero-bg">
        <img 
          src={hero}
          alt="Fence Installation Cape Cod" 
          className="hero-bg-image"
        />
        <div className="hero-overlay"></div>
      </div>

      <div className="hero-container">
        <div className="hero-content">
          <div className="trust-badge">
            <span className="badge-text2">{HERO.badge}</span>
          </div>
          
          <h1 className="hero-title">
            {HERO.title} <span className="highlight">{HERO.titleHighlight}</span>
          </h1>
          
          <p className="hero-description">
            {HERO.description}
          </p>

          {/* New Ratings Layout directly in Hero */}
          <div className="hero-ratings">
            {HERO.ratings.map((rating, idx) => (
              <a 
                key={idx}
                href={rating.url} 
                target="_blank" 
                rel="noopener noreferrer" 
                className="rating-box"
              >
                <div className={`platform-icon ${rating.icon}`}>
                  {getIcon(rating.icon)}
                </div>
                <div className="rating-details">
                  <div className="stars">
                    {[...Array(5)].map((_, i) => <FaStar key={i} />)}
                    <span className="score">{rating.score}</span>
                  </div>
                  <span className="platform-name">{rating.label}</span>
                </div>
              </a>
            ))}
          </div>

          <div className="hero-cta-group">
            <a href={BUSINESS.phoneHref} className="hero-cta-btn primary">
              {HERO.ctaPrimary} <FaChevronRight />
            </a>
            <a href="#quote" className="hero-cta-btn secondary">
              {HERO.ctaSecondary}
            </a>
          </div>
        </div>

        <div className="hero-right">
          <div className="review-card">
            <FaQuoteLeft className="quote-icon-top" />
            <p className="review-text-premium">
              {HERO.reviewerQuote}
            </p>
            <div className="reviewer-footer">
              <div className="reviewer-initials-box" aria-hidden="true">
                {reviewerInitials}
              </div>
              <div className="reviewer-meta">
                <span className="reviewer-name-new">{HERO.reviewerName}</span>
                <div className="reviewer-rating-new">
                  <div className="stars-row">
                    {[...Array(5)].map((_, i) => <FaStar key={i} />)}
                  </div>
                  <span className="score-new">5.0</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Hero Bottom Bar Nav (Desktop Only) */}
      <div className="hero-bottom-bar">
        <div className="bottom-bar-wrapper">
          <nav className="bottom-nav">
            {HERO.bottomNav.map((link, idx) => (
              <a key={idx} href={link.href} className="bottom-nav-link">
                <span className="nav-icon">{getIcon(link.icon)}</span>
                <span>{link.label}</span>
              </a>
            ))}
          </nav>
          <a href="#quote" className="bottom-cta">
            {HERO.bottomCtaText}
          </a>
        </div>
      </div>
    </section>
  );
};

export default Hero;
