import React from 'react';
import './cta.css';
import { FaPhoneAlt, FaCalendarCheck, FaAward, FaShieldAlt, FaCalculator } from 'react-icons/fa';
import { CTA as CTA_DATA, BUSINESS } from '../../content';
import ctaImage from '../../images/cta-bg.png';

const CTA: React.FC = () => {
  const getTrustIcon = (iconName: string) => {
    switch (iconName) {
      case 'award': return <FaAward />;
      case 'shield': return <FaShieldAlt />;
      case 'calculator': return <FaCalculator />;
      default: return <FaAward />;
    }
  };

  return (
    <section className="cta-section" id="quote">
      <div id="contact" style={{ position: 'absolute', top: 0 }}></div>
      <div className="cta-bg">
        <img src={ctaImage} alt="Premium Modern Fencing" />
        <div className="cta-overlay"></div>
      </div>

      <div className="cta-container">
        <div className="cta-content">
          <div className="cta-badge">{CTA_DATA.badge}</div>
          <h2 className="cta-title">
            {CTA_DATA.title} <br />
            <span className="cta-highlight">{CTA_DATA.titleHighlight}</span>
          </h2>
          <p className="cta-subtitle">
            {CTA_DATA.subtitle}
          </p>

          <div className="cta-actions">
            <a href={BUSINESS.phoneHref} className="cta-btn-primary">
              <FaPhoneAlt /> {CTA_DATA.ctaPrimaryText}
            </a>
            <a href="/contact" className="cta-btn-secondary">
              <FaCalendarCheck style={{ marginRight: '8px' }} /> {CTA_DATA.ctaSecondaryText}
            </a>
          </div>
        </div>

        <div className="cta-trust-grid">
          {CTA_DATA.trustItems.map((item, index) => (
            <div className="trust-item" key={index}>
              <div className="trust-icon">
                {getTrustIcon(item.icon)}
              </div>
              <h3>{item.title}</h3>
              <p>{item.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default CTA;

